const TTL_MS = 30_000;
const widgets = new Map<string, { widget: { id: string }; createdAt: number }>();
export function getWidget(id: string): { id: string } {
	const now = Date.now();
	const entry = widgets.get(id);
	if (entry !== undefined && now - entry.createdAt < TTL_MS) return entry.widget;
	const widget = { id };
	widgets.set(id, { widget, createdAt: now });
	return widget;
}
EOF
